// Bubble sort the array in place, then print it.
fn sort(xs) {
    let n = len(xs);
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n - 1 - i; j++) {
            if (xs[j] > xs[j + 1]) {
                let tmp = xs[j];
                xs[j] = xs[j + 1];
                xs[j + 1] = tmp;
            }
        }
    }
}

