fn search(xs, target) {
    let lo = 0;
    let hi = len(xs) - 1;
    while (lo <= hi) {
        let mid = int((lo + hi) / 2);
        if (xs[mid] == target) {
            return mid;
        }
        if (xs[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

