// Sieve of Eratosthenes: primes below 50.
let n = 50;

// isPrime[i] is true until i is shown to be composite.
let isPrime = [];
for (let i = 0; i < n; i++) {
    push(isPrime, true);
}
isPrime[0] = false;
isPrime[1] = false;

// Mark multiples of each prime p, starting at p * p.
for (let p = 2; p * p < n; p++) {
    if (isPrime[p]) {
        for (let j = p * p; j < n; j += p) {
            isPrime[j] = false;
        }
    }
}

// Collect the remaining primes.
let primes = [];
for (let i = 2; i < n; i++) {
    if (isPrime[i]) {
        push(primes, i);
    }
}

