fn balanced(s) {
    let stack = [];
    for (let i = 0; i < len(s); i++) {
        let c = s[i];
        if (c == "(" || c == "[" || c == "{") {
            push(stack, c);
        } else if (c == ")" || c == "]" || c == "}") {
            if (len(stack) == 0) { return false; }
            let opening = pop(stack);
            if ((c == ")" && opening != "(") || (c == "]" && opening != "[") || (c == "}" && opening != "{")) {
                return false;
            }
        }
    }
    return len(stack) == 0;
}
